const trig = $json;
const isCallback = !!trig.callback_query;
const msg = isCallback ? trig.callback_query.message : trig.message;
const chatId = msg && msg.chat ? String(msg.chat.id) : null;
return [{
  json: {
    chatId,
    isCallback,
    cbData: isCallback ? String(trig.callback_query.data || '') : null,
    cbId: isCallback ? trig.callback_query.id : null,
    text: !isCallback ? String((trig.message && trig.message.text) || '').trim() : null,
  },
}];

const sd = $getWorkflowStaticData('global');
if (!sd.admin) sd.admin = { awaiting: null, pendingCustomerId: null };
const st = sd.admin;
const ctx = $json;
const chatId = ctx.chatId;
const data = ctx.cbData || '';

function mainMenu() {
  return [
    { row: { buttons: [{ text: '📊 نظرة عامة', additionalFields: { callback_data: 'menu:overview' } }] } },
    { row: { buttons: [
      { text: '📨 التقارير المعلّقة', additionalFields: { callback_data: 'menu:pending_reports' } },
      { text: '▶️ شغّل التقارير الآن', additionalFields: { callback_data: 'menu:run_reports' } },
    ] } },
    { row: { buttons: [{ text: '💰 الضمانات المعلّقة', additionalFields: { callback_data: 'menu:guarantees' } }] } },
    { row: { buttons: [
      { text: '🔍 بحث عن عميل', additionalFields: { callback_data: 'menu:lookup' } },
      { text: '⏯️ تفعيل/إيقاف عميل', additionalFields: { callback_data: 'menu:toggle_status' } },
    ] } },
    { row: { buttons: [{ text: '🆘 نحتاجك (تنبيه لعميل)', additionalFields: { callback_data: 'menu:notice' } }] } },
  ];
}

let action = 'menu';
let replyText = null;
let keyboardRows = null;
let customerId = null;
let ledgerId = null;
let status = null;
let noticeText = null;
const answerCallback = ctx.isCallback;

if (ctx.isCallback && data === 'menu:main') {
  st.awaiting = null; st.pendingCustomerId = null;
  action = 'menu';
} else if (ctx.isCallback && data === 'menu:overview') {
  action = 'overview';
} else if (ctx.isCallback && data === 'menu:pending_reports') {
  action = 'pending_reports';
} else if (ctx.isCallback && data === 'menu:run_reports') {
  action = 'run_reports';
} else if (ctx.isCallback && data === 'menu:guarantees') {
  action = 'guarantees';
} else if (ctx.isCallback && data.startsWith('settle:')) {
  action = 'settle_guarantee';
  ledgerId = data.slice('settle:'.length);
} else if (ctx.isCallback && data === 'menu:lookup') {
  st.awaiting = 'lookup_id';
  action = 'simple_reply';
  replyText = 'اكتب رقم معرّف العميل (customer id):';
} else if (ctx.isCallback && data === 'menu:toggle_status') {
  st.awaiting = 'status_id';
  action = 'simple_reply';
  replyText = 'اكتب رقم معرّف العميل الذي تريد تفعيله/إيقافه:';
} else if (ctx.isCallback && data === 'menu:notice') {
  st.awaiting = 'notice_id';
  action = 'simple_reply';
  replyText = 'اكتب رقم معرّف العميل الذي تريد إرسال تنبيه له:';
} else if (ctx.isCallback && data.startsWith('status_choice:')) {
  action = 'set_status';
  customerId = st.pendingCustomerId;
  status = data.slice('status_choice:'.length);
  st.awaiting = null; st.pendingCustomerId = null;
} else if (!ctx.isCallback && ctx.text && st.awaiting === 'lookup_id') {
  action = 'lookup_customer';
  customerId = ctx.text.trim();
  st.awaiting = null;
} else if (!ctx.isCallback && ctx.text && st.awaiting === 'status_id') {
  st.pendingCustomerId = ctx.text.trim();
  st.awaiting = 'status_choice_pending';
  action = 'simple_reply';
  replyText = 'اختر الحالة الجديدة للعميل #' + st.pendingCustomerId + ':';
  keyboardRows = [{ row: { buttons: [
    { text: '▶️ تفعيل', additionalFields: { callback_data: 'status_choice:active' } },
    { text: '⏸️ إيقاف', additionalFields: { callback_data: 'status_choice:paused' } },
  ] } }];
} else if (!ctx.isCallback && ctx.text && st.awaiting === 'notice_id') {
  st.pendingCustomerId = ctx.text.trim();
  st.awaiting = 'notice_text';
  action = 'simple_reply';
  replyText = 'اكتب نص التنبيه الذي تريد إرساله للعميل #' + st.pendingCustomerId + ':';
} else if (!ctx.isCallback && ctx.text && st.awaiting === 'notice_text') {
  action = 'send_notice';
  customerId = st.pendingCustomerId;
  noticeText = ctx.text;
  st.awaiting = null; st.pendingCustomerId = null;
} else {
  action = 'menu';
}

if (action === 'menu') {
  replyText = 'لوحة تحكّم مسار 🌿\nاختر من القائمة:';
  keyboardRows = mainMenu();
}

return [{
  json: {
    chatId, action, replyText, keyboardRows, answerCallback,
    callbackQueryId: ctx.cbId, customerId, ledgerId, status, noticeText,
  },
}];

const chatId = $('موجّه القائمة').item.json.chatId;
const o = $json || {};
const lines = ['📊 نظرة عامة', ''];
lines.push('العملاء حسب الحالة: ' + JSON.stringify(o.customers_by_status || {}));
lines.push('تقديمات اليوم: ' + (o.sends_today ?? 0) + ' | آخر 7 أيام: ' + (o.sends_last_7_days ?? 0));
lines.push('ارتدادات اليوم: ' + (o.bounces_today ?? 0));
lines.push('طابور الإرسال: ' + JSON.stringify(o.send_queue_by_status || {}));
lines.push('صناديق البريد: ' + JSON.stringify(o.mail_links_by_status || {}));
lines.push('تقارير معلّقة: ' + (o.pending_reports ?? 0));
lines.push('ضمانات معلّقة: ' + (o.pending_guarantees ?? 0));
lines.push('وضع التجربة (DRY_RUN): ' + (o.dry_run ? 'مفعّل' : 'متوقف'));
return [{ json: { chatId, text: lines.join('\n'), keyboardRows: null } }];

const chatId = $('موجّه القائمة').item.json.chatId;
const items = ($json && $json.items) || [];
const text = items.length === 0
  ? 'لا توجد تقارير معلّقة الآن.'
  : ('📨 تقارير معلّقة (' + items.length + '):\n' + items.map((r) => '#' + r.id + ' — عميل ' + r.customer_id + ' — ' + r.report_date).join('\n'));
return [{ json: { chatId, text, keyboardRows: null } }];

const chatId = $('موجّه القائمة').item.json.chatId;
const r = $json || {};
const text = '✅ تشغيل التقارير: أُنشئ ' + (r.created ?? 0) + '، موجود مسبقًا ' + (r.already_existed ?? 0)
  + '، أخطاء ' + (r.errors ?? 0) + ' (من أصل ' + (r.customers_active ?? 0) + ' عميلًا نشطًا).';
return [{ json: { chatId, text, keyboardRows: null } }];

const chatId = $('موجّه القائمة').item.json.chatId;
const items = ($json && $json.items) || [];
let text, keyboardRows = null;
if (items.length === 0) {
  text = 'لا توجد ضمانات بانتظار التسوية الآن.';
} else {
  text = '💰 ضمانات بانتظار التسوية (' + items.length + '):\n' + items.map((g) =>
    '#' + g.id + ' — ' + (g.customer_name || ('عميل ' + g.customer_id)) + ' — العجز ' + g.shortfall
    + ' — المبلغ ' + (g.refund_amount ?? 'غير محدد (يحتاج تعبئة customers.price_sar)')
  ).join('\n');
  keyboardRows = items.slice(0, 20).map((g) => ({
    row: { buttons: [{ text: '✅ تسوية #' + g.id, additionalFields: { callback_data: 'settle:' + g.id } }] },
  }));
}
return [{ json: { chatId, text, keyboardRows } }];

const chatId = $('موجّه القائمة').item.json.chatId;
const r = $json || {};
const text = r.ok
  ? ('✅ تمت تسوية الضمان #' + r.id + (r.already_settled ? ' (كانت مُسوّاة مسبقًا)' : '') + '.')
  : 'تعذّرت تسوية الضمان، تحقق من الرقم.';
return [{ json: { chatId, text, keyboardRows: null } }];
